    Bug 1941770 - Show better error message if local folder cannot be compacted because of a storage corruption. r=#thunderbird-back-end-reviewers

    Differential Revision: https://phabricator.services.mozilla.com/D234325

diff --git a/mail/locales/en-US/chrome/messenger/messenger.properties b/mail/locales/en-US/chrome/messenger/messenger.properties
index b84f3f1ff78..369e7b27f9f 100644
--- a/mail/locales/en-US/chrome/messenger/messenger.properties
+++ b/mail/locales/en-US/chrome/messenger/messenger.properties
@@ -71,6 +71,7 @@ deletingMsgsFailed=Unable to delete messages in folder %S because it is in use b
 alertFilterCheckbox=Do not warn me again.
 compactFolderDeniedLock=The folder '%S' cannot be compacted because another operation is in progress. Please try again later.
 compactFolderWriteFailed=The folder '%S' could not be compacted because writing to folder failed. Verify that you have enough disk space, and that you have write privileges to the file system, then try again.
+compactFolderStorageCorruption=The folder '%S' could not be compacted because it contains unexpected data.
 compactFolderInsufficientSpace=Some folders (e.g. '%S') cannot be compacted because there is not enough free disk space. Please delete some files and try again.
 filterFolderHdrAddFailed=The messages could not be filtered to folder '%S' because adding a message to it failed. Verify that the folder is displaying properly or try to repair it from the folder properties.
 filterFolderWriteFailed=The messages could not be filtered to folder '%S' because writing to folder failed. Verify that you have enough disk space, and that you have write privileges to the file system, then try again.
diff --git a/mailnews/base/src/FolderCompactor.cpp b/mailnews/base/src/FolderCompactor.cpp
index d21042c4487..d1769502e84 100644
--- a/mailnews/base/src/FolderCompactor.cpp
+++ b/mailnews/base/src/FolderCompactor.cpp
@@ -846,8 +846,7 @@ void BatchCompactor::OnDone(nsresult status, int64_t bytesRecovered) {
         } else {
           // For local folders, there's not much we can do. If compact can't
           // scan the mbox, then local folder repair won't be able to either.
-          // Show a catch-all error message.
-          folder->ThrowAlertMsg("compactFolderWriteFailed", mWindow);
+          folder->ThrowAlertMsg("compactFolderStorageCorruption", mWindow);
         }
       } else {
         // Show a catch-all error message.
